// Setting a secure, CSRF-resistant cookie in Next.js Middleware
import { NextResponse } from 'next/server';

export function middleware(request) {
  const response = NextResponse.next();

  response.cookies.set('session_token', '12345abcde', {
    httpOnly: true, // Prevents XSS from stealing the cookie
    secure: true,   // Only sent over HTTPS

    // 🛡️ THE CSRF DEFENSE 🛡️
    // 'Strict' means the browser will NEVER send this cookie 
    // if the request comes from an external website.
    sameSite: 'strict', 
  });

  return response;
}
